    panel.setAttribute('translate', 'no');
    panel.setAttribute('dir', 'ltr');
    var head = el('div', 'aiva-translate-head');
    var brand = el('div', 'aiva-translate-brand');
    brand.innerHTML = GLOBE + '<span><strong>Aiva Translate</strong><small>' + (LANGS.length + 1) + ' languages</small></span>';
    var close = el('button', 'aiva-translate-close');
    close.type = 'button'; close.setAttribute('aria-label', 'Close'); close.innerHTML = '&times;';
    close.addEventListener('click', function () { closePanel(true); });
    head.appendChild(brand); head.appendChild(close);
    var english = el('button', 'aiva-translate-english', 'Return to English');
    english.type = 'button';
    english.addEventListener('click', function () { choose('en'); });
    search = el('input', 'aiva-translate-search');
    search.type = 'search';
    search.setAttribute('aria-label', 'Search languages');
    search.placeholder = 'Search languages · ' + (LANGS.length + 1) + ' available';
    search.autocomplete = 'off'; search.spellcheck = false;
