    search.addEventListener('keydown', function (e) {
      if (e.key === 'ArrowDown') { e.preventDefault(); var f = list.querySelector('button'); if (f) f.focus(); }
      if (e.key === 'Enter') { var g = list.querySelector('button'); if (g) { e.preventDefault(); g.click(); } }
    });
    list = el('div', 'aiva-translate-list');
    list.setAttribute('role', 'listbox');
    list.setAttribute('aria-label', 'Languages');
    list.addEventListener('keydown', function (e) {
      var items = Array.prototype.slice.call(list.querySelectorAll('button')), i = items.indexOf(document.activeElement);
      if (e.key === 'ArrowDown' && i < items.length - 1) { e.preventDefault(); items[i + 1].focus(); }
      if (e.key === 'ArrowUp') { e.preventDefault(); (i > 0 ? items[i - 1] : search).focus(); }
    });
    var foot = el('p', 'aiva-translate-foot', 'Machine translation on aivatrading.uk. English is the authoritative version for prices, orders and terms.');
    panel.appendChild(head); panel.appendChild(search); panel.appendChild(english); panel.appendChild(list); panel.appendChild(foot);
    panel.addEventListener('keydown', function (e) { if (e.key === 'Escape') closePanel(true); });
